import com.franchiseguide.app.model.*
import java.time.*
import java.io.File
private var assertions=0
private fun test(name:String,v:Boolean){check(v){name};assertions++;println("PASS $name")}
private fun rejects(name:String,block:()->Unit)=test(name,runCatching(block).isFailure)
fun main(args:Array<String>){
 val d1=Instant.parse("2026-10-01T12:00:00Z").toEpochMilli();val d2=Instant.parse("2026-10-02T12:00:00Z").toEpochMilli();val now=Instant.parse("2026-10-06T12:00:00Z").toEpochMilli()
 val b=MediaItem("book",kind=MediaKind.BOOK,title="Livre test",progressTotal=100,progressUnit="pages")
 val first=ProgressRules.update(b,100,100,now=d1)
 test("First finish records one reading",first.watched&&first.plays==1&&first.watchHistory==listOf(d1))
 test("Second save is not a replay",ProgressRules.update(first,100,100,now=d2).watchHistory==listOf(d1))
 val started=ProgressRules.restart(first)
 test("Restart preserves known endings",started.watched&&started.plays==1&&started.watchHistory==listOf(d1))
 test("Restart resets only current progress",started.progressCurrent==0&&ProgressRules.status(started)=="active")
 test("Restart is in progress despite past ending",started.isInProgress)
 val lower=ProgressRules.update(first,10,100,now=d2)
 test("Lowering progress preserves last known date",lower.lastWatchedAt==d1&&lower.watchHistory==listOf(d1)&&lower.watched)
 val second=ProgressRules.update(started,100,100,now=d2)
 test("Finishing a new run records both dates",second.plays==2&&second.watchHistory==listOf(d1,d2))
 for(status in listOf("paused","abandoned","planned")){
  val m=ProgressRules.update(first,10,100,state=status)
  test("State $status is stored independently",ProgressRules.status(m)==status)
  test("State $status never clears history",m.watched&&m.plays==1&&m.lastWatchedAt==d1)
 }
 val custom=ProgressRules.update(b.copy(kind=MediaKind.GAME),15,15,unit="missions",platform="PS5",minutes=180,now=d1)
 test("Completion retains personal platform and minutes",custom.personalPlatform=="PS5"&&custom.playtimeMinutes==180)
 test("Completion retains supplied total and unit",custom.progressCurrent==15&&custom.progressTotal==15&&custom.progressUnit=="missions")
 test("Unknown total never auto-completes",!ProgressRules.update(b,500,0).watched)
 test("Explicit completion with unknown total works",ProgressRules.update(b,500,0,state="completed",now=d1).watched)
 test("Blank gaming time is unknown, not 0",ProgressRules.update(custom,1,15,minutes=null).playtimeMinutes==null)
 test("Explicit clear removes history",ProgressRules.clear(first).let{!it.watched&&it.watchHistory.isEmpty()&&it.plays==0&&it.lastWatchedAt==null})
 test("Finish active rerun adds a date",ProgressRules.finish(started,d2).plays==2)
 test("Idempotent finish stays idempotent",ProgressRules.finish(first,d2).plays==1)
 test("Explicit replay adds a date",ProgressRules.finish(first,d2,true).plays==2)
 rejects("Negative progress rejected"){ProgressRules.update(b,-1,100)}
 rejects("Progress above known total rejected"){ProgressRules.update(b,101,100)}
 rejects("Invalid state rejected"){ProgressRules.update(b,1,100,state="maybe")}
 rejects("Fractional text rejected"){ProgressRules.parse("1.5","Actuel")}
 rejects("Excessive text integer rejected"){ProgressRules.parse("99999999999999","Actuel")}
 rejects("Movie progress rejected"){ProgressRules.update(b.copy(kind=MediaKind.MOVIE),1,2)}
 test("Input object unchanged",b.plays==0&&b.progressCurrent==0&&!b.watched)
 fun query(kind:String="all",from:LocalDate?=null,to:LocalDate?=null,hidden:Boolean=false,specials:Boolean=false,fav:Boolean=false,text:String="")=InsightsRules.Query(kind,from,to,hidden,specials,fav,text,now,ZoneId.of("UTC"))
 fun analyse(m:List<MediaItem>,e:List<Episode> = emptyList(),g:GamingState=GamingState(),q:InsightsRules.Query=query())=InsightsRules.analyse(m,e,g,q)
 val movie=MediaItem("movie",kind=MediaKind.MOVIE,title="Film témoin",watched=true,plays=3,lastWatchedAt=d2,watchHistory=listOf(d1,d2),runtimeMinutes=100)
 val show=MediaItem("show",kind=MediaKind.SHOW,title="Série témoin",lastWatchedAt=d2,watched=true,catalogComplete=true,episodeCount=1)
 val ep=Episode("ep","show",1,1,"Pilote",null,watched=true,plays=1,watchHistory=listOf(d1),runtimeMinutes=45)
 val basic=analyse(listOf(movie,show,first),listOf(ep))
 test("Series aggregate date is not an extra reading",basic.totalPlays==5L&&basic.knownDates==4)
 test("Old unknown movie reading is disclosed",basic.undatedPlays==1L)
 test("Video unique durations never count book time",basic.uniqueMinutes==145L)
 test("Video replay durations use counts only for actual video",basic.allMinutes==345L)
 test("Book reading is still a dated event",basic.byKind.getValue("book").knownDates==1)
 test("Known daily history includes all kinds",basic.days.sumOf{it.events}==4)
 test("Catch up requires loaded complete series",basic.caughtUp==1)
 test("Incomplete series is not caught up",analyse(listOf(show.copy(catalogComplete=false)),listOf(ep)).caughtUp==0)
 test("Missing announced episodes is not caught up",analyse(listOf(show.copy(episodeCount=2)),listOf(ep)).caughtUp==0)
 test("Empty series is not caught up",analyse(listOf(show)).caughtUp==0)
 val unknown=analyse(listOf(movie.copy(runtimeMinutes=null),b.copy(watched=true,plays=6,lastWatchedAt=null)))
 test("Missing movie runtime is not invented",unknown.allMinutes==0L&&unknown.unknownVideoPlays==3L)
 test("Six undated book readings stay undated",unknown.byKind.getValue("book").undated==6L)
 test("Zero runtime is unknown duration",analyse(listOf(movie.copy(runtimeMinutes=0))).unknownVideoPlays==3L)
 val recent=analyse(listOf(movie,first),q=query(from=LocalDate.parse("2026-10-02"),to=LocalDate.parse("2026-10-02")))
 test("Date range applies to dated records only",recent.events.size==1&&recent.events[0].kind=="movie")
 test("Date range does not change historical known count",recent.knownDates==3&&recent.totalPlays==4L)
 test("Range video uses one date, not all counts",recent.windowMinutes==100L)
 val future=analyse(listOf(first.copy(plays=2,watchHistory=listOf(d1,now+1000),lastWatchedAt=now+1000)))
 test("Future history dates excluded",future.futureDates==1&&future.events.size==1&&future.undatedPlays==1L)
 test("History search accent insensitive",analyse(listOf(movie),q=query(text="temoin")).events.size==2)
 test("Search leaves current selection unchanged",analyse(listOf(movie),q=query(text="unmatched")).let{it.events.isEmpty()&&it.media.size==1})
 test("Kind filter restricts records",analyse(listOf(movie,first),q=query(kind="book")).events.size==1)
 rejects("Inverted date range rejected"){analyse(listOf(movie),q=query(from=LocalDate.parse("2026-10-06"),to=LocalDate.parse("2026-10-01")))}
 test("Orphan episodes excluded",analyse(emptyList(),listOf(ep)).events.isEmpty())
 test("Removed parent excludes episodes",analyse(listOf(show.copy(added=false)),listOf(ep)).events.isEmpty())
 test("Suggestions excluded",analyse(listOf(first.copy(isSuggestion=true))).media.isEmpty())
 test("Hidden excluded by default",analyse(listOf(first.copy(hidden=true))).events.isEmpty())
 test("Hidden explicit inclusion",analyse(listOf(first.copy(hidden=true)),q=query(hidden=true)).events.size==1)
 test("Favorites filter retains only favorites",analyse(listOf(first,movie.copy(favorite=true)),q=query(fav=true)).media.size==1)
 test("Specials excluded by default",analyse(listOf(show),listOf(ep.copy(season=0))).events.isEmpty())
 test("Specials explicitly included",analyse(listOf(show),listOf(ep.copy(season=0)),q=query(specials=true)).events.size==1)
 test("Skipped view does not count as watched reading",analyse(listOf(show),listOf(ep.copy(skipped=true))).events.isEmpty())
 val books=listOf(first.copy(progressCurrent=20,trackingStatus="active"),b.copy(id="b2",progressCurrent=10,progressUnit="PAGE"),b.copy(id="b3",progressCurrent=80,progressUnit="%"),b.copy(id="b4",progressCurrent=5,progressUnit="chapitres"))
 val pageAnalysis=analyse(books)
 test("Pages sum only current page units",pageAnalysis.currentPages==30L)
 test("Other reading units disclosed separately",pageAnalysis.pageBooks==2&&pageAnalysis.otherUnitBooks==2)
 test("Previously read can also be active",pageAnalysis.statuses.getValue("book").getValue("active")==4&&pageAnalysis.byKind.getValue("book").plays==1L)
 val profileA=GamingAccount("a","steam","76561198000000001","Profil privé A")
 val profileB=GamingAccount("b","steam","76561198000000002","Profil privé B")
 val g1=MediaItem("g1",kind=MediaKind.GAME,title="G1",steam=SteamGameMetadata("570",mapOf(profileA.externalId to SteamPlaytime(60,null),profileB.externalId to SteamPlaytime(120,null))),playtimeMinutes=25)
 val g2=g1.copy(id="g2",playtimeMinutes=null,steam=SteamGameMetadata("570",mapOf(profileA.externalId to SteamPlaytime(80,null))))
 val gamers=GamingState(accounts=listOf(profileA,profileB))
 val steamA=analyse(listOf(g1,g2),g=gamers)
 test("Steam profiles remain separated",steamA.steam.map{it.minutes}==listOf(80L,120L))
 test("Same App ID deduped using maximum known snapshot",steamA.steam.first().games==1&&steamA.steam.first().duplicates==1)
 test("Declared minutes separate from Steam",steamA.declaredGameMinutes==25L&&steamA.declaredGameCount==1)
 test("Steam hours are not history events",steamA.totalPlays==0L&&steamA.events.isEmpty())
 val missingSteam=analyse(listOf(g1.copy(steam=SteamGameMetadata("570",mapOf(profileA.externalId to SteamPlaytime(null,null))))),g=gamers)
 test("Unknown Steam time not treated as a known zero",missingSteam.steam.single().unknownGames==1&&missingSteam.steam.single().knownGames==0)
 val achievements=listOf(GameAchievement("a1","A1",earned=true,hardcoreEarned=true,localDone=true),GameAchievement("a2","A2",earned=null,localDone=true))
 val set=AchievementSet("set","g1","steam","PC","570","Set",accountId="a",achievements=achievements,completeCatalog=true)
 val trophies=analyse(listOf(g1),g=gamers.copy(sets=listOf(set))).successSets.single()
 test("Normal earned count is not inflated",trophies.earned==1&&trophies.total==2)
 test("Hardcore and checklist separate",trophies.hardcore==1&&trophies.localDone==2&&trophies.unknown==1)
 test("Unknown achievement prevents completeness",!trophies.complete&&!trophies.platinum)
 test("Empty set is not complete",analyse(listOf(g1),g=gamers.copy(sets=listOf(set.copy(achievements=emptyList())))).successSets.single().complete==false)
 test("Hidden game success data excluded",analyse(listOf(g1.copy(hidden=true)),g=gamers.copy(sets=listOf(set))).successSets.isEmpty())
 // Small deterministic cross-platform aggregate, serialized without a test parser dependency.
 val parity=analyse(listOf(movie,show,first,g1,g2),listOf(ep),gamers.copy(sets=listOf(set)),query())
 val json="""{"titles":${parity.media.size},"episodes":${parity.episodes.size},"plays":${parity.totalPlays},"known":${parity.knownDates},"undated":${parity.undatedPlays},"windowMinutes":${parity.windowMinutes},"uniqueMinutes":${parity.uniqueMinutes},"allMinutes":${parity.allMinutes},"pages":${parity.currentPages},"declaredMinutes":${parity.declaredGameMinutes},"caughtUp":${parity.caughtUp},"steamMinutes":[${parity.steam.joinToString(","){it.minutes.toString()}}],"normal":${parity.successSets.single().earned},"hardcore":${parity.successSets.single().hardcore},"local":${parity.successSets.single().localDone}}"""
 if(args.isNotEmpty())File(args[0]).writeText(json)
 println("InsightsProgressRules: $assertions assertions passed; JVM domain only, no Android device.")
}
